export async function listTools() {
  return [
    {
      name: 'run_with_progress',
      description: 'Run a task reporting monotonic progress from 0 to 1.',
      inputSchema: {
        type: 'object',
        properties: {
          steps: { type: 'integer', minimum: 1, description: 'Number of steps to run (positive integer).' }
        },
        required: ['steps']
      }
    }
  ];
}

export async function callTool(name, args = {}, extra = {}) {
